    /**
     * Tests creating a new InventoryItem.
     *
     * @return    InventoryItem
     */
    public InventoryItem testCreate() throws Throwable {
    InventoryItem entity = null;

    LOGGER.info( "InventoryItemTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a InventoryItem");

    StringBuilder msg = new StringBuilder( "-- Failed to create a InventoryItem" );

    try {
        entity = service.createInventoryItem( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getInventoryItemId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a InventoryItem with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

