    /**
     * Tests getting all InventoryItems.
     *
     * @return    Collection
     */
    public List<InventoryItem> testGetAll() throws Throwable {
    LOGGER.info( "InventoryItemTest:testGetAll() - Retrieving Collection of InventoryItems:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all InventoryItem : " );
    List<InventoryItem> collection  = null;

    try {
        // call the static get method on the InventoryItemService
        collection = service.getAllInventoryItem();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            InventoryItem currEntity  = null;
            Iterator<InventoryItem> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getInventoryItemId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

